-- 372_seed_cash_ledger_from_kiyo_sheet.sql
-- きよが手入力しているスプレッドシート「収支」の口座タブを cash_ledger_entries へ移す。
-- 一次情報: https://docs.google.com/spreadsheets/d/1Q8cEnutfJzgdEXKIRDb4wUGAe6ON1MMiiz3irCrj1YA
--   タブ「2026年_PayPay」(gid=936820752) と「商工中金」。2026-09-04 時点の内容。
--
-- 移植の方針:
--   - スプシの行をそのまま1行として入れる。金額も残高も原本のまま持つ。
--     きよの手入力には残高が飛んでいる箇所 (商工中金 9/30 で残高がリセットされている等) があるが、
--     ここで直すと原本と突き合わせられなくなるので直さない。画面側で「原本の残高」と
--     「OSが積み上げた残高」を並べて出し、食い違う行を見つけられるようにする。
--   - entry_date が 2026-09-04 より後の行は予定 (is_planned = true)。
--   - 再取込で二重に増えないよう (account_id, source, source_row) を一意キーにしている。
--
-- 取り込み日 2026-09-04

BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '120s';
SELECT pg_advisory_xact_lock(hashtext('seed_cash_ledger_kiyo_sheet'));

DELETE FROM public.cash_ledger_entries WHERE source = 'sheet_import';
DELETE FROM public.loan_events WHERE source = 'sheet_import';

